import type {QuestionValues} from "./QuestionEditor";

type Draft={p:string;a:string;d:string[];e:string;short?:string[];exact?:boolean};
type Seed=QuestionValues&{seed_id:string};
const mc=(p:string,a:string,d:string[],e:string):Draft=>({p,a,d,e});
const keyboard=(value:string)=>value.replace(/[₀-₉]/g,c=>`_${"₀₁₂₃₄₅₆₇₈₉".indexOf(c)}`).replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]/g,c=>`^${"⁰¹²³⁴⁵⁶⁷⁸⁹".indexOf(c)}`).replace(/[−–]/g,"-").replace(/log_(\d)(?=[0-9A-Za-z])/g,"log_$1 ");
const sa=(p:string,a:string|string[],e:string,exact=false):Draft=>{const values=Array.isArray(a)?a:[a],accepted=[...values];for(const value of values){const dollar=value.startsWith("$")?value.replace(/^\$\s*/,"").replaceAll(",",""):"";if(dollar&&!accepted.includes(dollar))accepted.push(dollar);const unitless=value.replace(/\s*(?:cm|mm|km|m|°|m²|cm²|mm²|m³|cm³|mm³)\s*$/i,"");if(unitless!==value&&!accepted.includes(unitless))accepted.push(unitless);const typed=keyboard(value);if(typed!==value&&!accepted.includes(typed))accepted.push(typed)}return {p,a:values[0],d:[],e,short:accepted,exact}};
let choice=0;
function bank(code:string,items:Draft[]):Seed[]{if(items.length!==21)throw new Error(`${code}: expected 21 questions, got ${items.length}`);const sectionHex=[...code].map(char=>char.charCodeAt(0).toString(16).padStart(2,"0")).join("");return items.map((q,i)=>{const seed_id=`10c80000-0000-4000-8000-${sectionHex}${String(i+1).padStart(12-sectionHex.length,"0")}`;if(q.short)return {prompt:q.p,options:{kind:"short_answer",accepted:q.short,exact:q.exact},correct_index:0,explanation:q.e,seed_id};const slot=choice++%4,options=[...q.d];options.splice(slot,0,q.a);return {prompt:q.p,options,correct_index:slot,explanation:q.e,seed_id};});}

